const moduleMeta: Record<Module, { eyebrow: string; title: string; description: string }> = {
  dashboard: { eyebrow: "نظرة تنفيذية", title: "وضع الشركة المالي", description: "ملخص واضح ومباشر؛ ستظهر الأرقام من دفتر الأستاذ بعد إكمال الإعداد وترحيل العمليات." },
  accountant: { eyebrow: "Desk View", title: "لوحة المحاسب", description: "أولوية مهام التشغيل المالي من الموردين وVAT والامتثال وميزان المراجعة." },
  sales: { eyebrow: "قسم المبيعات", title: "قسم المبيعات", description: "أدر العملاء وCRM والفرص والزيارات وعروض الأسعار فقط؛ ستجد الفواتير في قسم الفوترة المستقل." },
  billing: { eyebrow: "قسم الفوترة", title: "الفوترة والتحصيلات", description: "أنشئ الفواتير وتابع تحويل العروض والتحصيلات والمتأخرات ضمن صلاحيتك المالية." },
  accounting: { eyebrow: "دفتر الأستاذ", title: "سلامة القيد قبل الترحيل", description: "المدين والدائن يحسبان في الخادم بقواعد عشرية حتمية لا في المتصفح." },
  operations: { eyebrow: "العمليات المالية", title: "الموردون والمصروفات والبنوك", description: "سجّل الموردين والمصروفات والحسابات البنكية مع إنشاء قيود مرتبطة قابلة للتتبع." },
  tax: { eyebrow: "VAT و FATOORA", title: "مركز الامتثال", description: "طبقة قواعد قابلة للإصدار؛ لا تعني حالة الواجهة اعتماداً رسمياً أو جاهزية إنتاجية." },
  documents: { eyebrow: "Document Room", title: "غرفة المستندات المالية", description: "سيتم ربط العقود والقوائم والمستندات الضريبية بالسجل المالي مع تصنيف وأثر وصول." },
  audit: { eyebrow: "External Audit", title: "مركز مراجعة الإقفال", description: "وحدة وصول مقيد للمراجع القانوني تربط الإقفال بالتقرير والتوقيع وإقرار الاستقلالية." },
  settings: { eyebrow: "Company Setup", title: "تهيئة مساحة العمل", description: "أنشئ المستأجر والشركة ثم أكمل البيانات الضريبية والفروع والسياسات ضمن معالج الإعداد." },
};

const formatMoney = (value?: string) => value ? new Intl.NumberFormat("en-US", { style: "currency", currency: "SAR", minimumFractionDigits: 2 }).format(Number(value)) : "—";

export default function Workspace({ module }: { module: Module }) {
  const { isAuthenticated, user } = useAuth();
  const baseMeta = moduleMeta[module];
  const workspaces = trpc.finance.listMyWorkspaces.useQuery(undefined, { enabled: isAuthenticated });
  const [checkedInvitations, setCheckedInvitations] = useState(false);
  const acceptInvitations = trpc.team.acceptMyInvitations.useMutation({ onSuccess: async (result) => { if (result.accepted) { toast.success("تم تفعيل دعوتك إلى مساحة العمل."); await workspaces.refetch(); } } });
  useEffect(() => { if (!isAuthenticated || checkedInvitations) return; setCheckedInvitations(true); acceptInvitations.mutate(); }, [isAuthenticated, checkedInvitations, acceptInvitations]);
  const activeWorkspace = selectActiveWorkspace(workspaces.data);
  const roleCode = user?.role === "admin" ? "super_admin" : activeWorkspace?.role?.code;
  const meta = module === "dashboard" && roleCode === "general_manager"
    ? { eyebrow: "Executive Command Center", title: "لوحة قيادة الشركة", description: "رؤية تنفيذية موحدة للأداء والموافقات والمخاطر والفرص، مع إبقاء التفاصيل التشغيلية ضمن أصحابها." }
    : baseMeta;
  const restrictedPaths: Record<string, string[]> = { sales: ["/", "/sales", "/billing"], sales_rep: ["/", "/sales"], cfo: ["/", "/accountant", "/billing", "/accounting", "/accounts", "/operations", "/tax", "/documents", "/audit"], finance_manager: ["/", "/accountant", "/billing", "/accounting", "/accounts", "/operations", "/tax", "/documents", "/audit"], external_auditor: ["/", "/audit", "/documents"], read_only: ["/"], ceo_assistant: ["/", "/sales"], operations_manager: ["/"], executive_assistant: ["/"], company_admin: ["/"], general_manager: ["/"], };
  const modulePath = module === "dashboard" ? "/" : `/${module}`;
  const roleDenied = Boolean(activeWorkspace && roleCode && restrictedPaths[roleCode] && !restrictedPaths[roleCode].includes(modulePath));

  if (isAuthenticated && workspaces.isLoading) return <DashboardLayout><WorkspaceLoadingState /></DashboardLayout>;
  if (isAuthenticated && workspaces.isError) return <DashboardLayout><WorkspaceUnavailableState message="تعذر تحميل عضوية مساحة العمل. أعد المحاولة بعد التأكد من اتصال الشبكة." /></DashboardLayout>;
  if (isAuthenticated && !activeWorkspace) return <DashboardLayout><WorkspaceUnavailableState message="لا توجد عضوية نشطة مرتبطة بشركة. اطلب من مدير النظام ربط الحساب بالشركة الصحيحة." /></DashboardLayout>;

  if (roleDenied) return <DashboardLayout><div className="mx-auto flex min-h-[60vh] max-w-xl items-center justify-center" dir="rtl"><Card className="w-full border-0 bg-white text-center shadow-sm"><CardContent className="space-y-3 p-8"><ShieldCheck className="mx-auto h-10 w-10 text-[#0b3d3a]" /><h1 className="text-xl font-bold text-[#18332f]">هذه الصفحة غير ضمن دورك</h1><p className="text-sm leading-6 text-[#6b766f]">ستظهر لك لوحة العمل والمهام المرتبطة بدورك فقط. إذا كنت تحتاج صلاحية إضافية، اطلب اعتمادها من مدير الشركة.</p></CardContent></Card></div></DashboardLayout>;

  return <DashboardLayout>
    <div className="mx-auto max-w-[1440px] space-y-6">
      <header className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-xs font-bold tracking-[0.16em] text-[#5c7b6c] uppercase">{meta.eyebrow}</p>
          <h1 className="mt-2 text-3xl font-bold tracking-tight text-[#102d2b]">{meta.title}</h1>
          <p className="mt-2 max-w-2xl text-sm leading-6 text-[#64716a]">{meta.description}</p>
        </div>
        <div className="flex items-center gap-2">
          {workspaces.isLoading ? <Badge variant="outline" className="px-3 py-1.5">جارٍ تحميل مساحة العمل</Badge> : activeWorkspace?.tenant ? <Badge className="bg-[#e6f0eb] text-[#0b3d3a] hover:bg-[#e6f0eb] px-3 py-1.5">{activeWorkspace.tenant.legalName}</Badge> : <Badge variant="outline" className="px-3 py-1.5">مساحة العمل غير مهيأة</Badge>}
        </div>
      </header>
      {module === "dashboard" && <><SmartOnboardingGate tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} />{roleCode === "super_admin" ? <CompanyAdminWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} roleCode={roleCode} /> : (roleCode === "cfo" || roleCode === "finance_manager") ? <FinanceAccountingManagerWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /> : roleCode === "company_admin" ? <CompanyAdminWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} roleCode={roleCode} /> : roleCode === "general_manager" ? <CeoCommandCenterWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /> : roleCode === "ceo_assistant" ? <AdministrativeAssistantWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /> : roleCode === "operations_manager" ? <OperationsManagerWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /> : roleCode === "executive_assistant" ? <ExecutiveAssistantWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /> : <><RoleWorkspaceDashboard roleCode={activeWorkspace?.role?.code} roleName={activeWorkspace?.role?.nameAr} /><KpiDashboard tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ExecutiveDashboard isLoading={workspaces.isLoading} hasWorkspace={Boolean(activeWorkspace)} tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ExecutiveCoordinationBoard tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} roleCode={roleCode} /></>}
</>}
      {module === "accountant" && <><AccountantDashboard tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
      {module === "sales" && <><SalesWorkbench tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} roleCode={roleCode} />{roleCode !== "ceo_assistant" && <CustomerPortalManager tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} />}</>}
      {module === "billing" && <BillingWorkbench tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} roleCode={roleCode} />}
      {module === "accounting" && <><AccountingWorkbench tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><LedgerReport tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><DetailedFinancialReports tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
      {module === "operations" && <><OperationsConsole tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ExpenseEntryWithDimensions tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><SupplierInvoiceWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><BankReconciliationPanel tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
      {module === "tax" && <><TaxCenter tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><VatReturnWorkspace tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ApprovalCenter tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
      {module === "documents" && <><DocumentRoom tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><DocumentExtraction tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><DocumentRetentionManager tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
      {module === "audit" && <><AuditReviewCenter tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><AuditControlEvidence tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
      {module === "settings" && <><SmartOnboardingPanel tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><CompanyAdministration tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><BrandingSettings tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} roleCode={roleCode} /><SubscriptionSettings tenantId={activeWorkspace?.tenant.id} roleCode={roleCode} /><CustomerPortalManager tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ApprovalCenter tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><SecurityEventsPanel /><MfaSecurityPanel /><TeamManagement tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><DimensionsManager tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><TaxInvoicingSettings tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ZatcaSettingsPanel tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /><ScheduleSettings tenantId={activeWorkspace?.tenant.id} companyId={activeWorkspace?.company?.id} /></>}
    </div>
  </DashboardLayout>;
}

function WorkspaceLoadingState() {
  return <div className="mx-auto flex min-h-[60vh] max-w-xl items-center justify-center" dir="rtl"><Card className="w-full border-0 bg-white text-center shadow-sm"><CardContent className="space-y-4 p-8"><Loader2 className="mx-auto h-10 w-10 animate-spin text-[#0b3d3a]" /><h1 className="text-xl font-bold text-[#18332f]">جارٍ تحميل مساحة العمل</h1><p className="text-sm leading-6 text-[#6b766f]">نتحقق من الشركة والدور قبل عرض اللوحة المناسبة. لن يتم عرض لوحة قراءة أو صلاحيات افتراضية أثناء التحميل.</p></CardContent></Card></div>;
}

function WorkspaceUnavailableState({ message }: { message: string }) {
  return <div className="mx-auto flex min-h-[60vh] max-w-xl items-center justify-center" dir="rtl"><Card className="w-full border-0 border-[#ead8d4] bg-white text-center shadow-sm"><CardContent className="space-y-3 p-8"><AlertCircle className="mx-auto h-10 w-10 text-[#a24b3c]" /><h1 className="text-xl font-bold text-[#18332f]">مساحة العمل غير متاحة</h1><p className="text-sm leading-6 text-[#6b766f]">{message}</p></CardContent></Card></div>;
}

function SmartOnboardingGate({ tenantId, companyId }: { tenantId?: number; companyId?: number }) {
  const [, navigate] = useLocation();
  const enabled = Boolean(tenantId && companyId);
  const status = trpc.finance.onboardingStatus.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  if (!enabled || status.isLoading || status.isError || !status.data || status.data.isReady) return null;
  return <Card className="border-0 bg-[#f7fbf8] shadow-sm" dir="rtl"><CardHeader className="pb-3"><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle className="flex items-center gap-2 text-base text-[#18332f]"><Sparkles className="h-5 w-5 text-[#b0782c]" />ابدأ بتجهيز شركتك</CardTitle><p className="mt-1 text-sm leading-6 text-[#64716a]">أكمل الإعداد الذكي قبل إصدار أول فاتورة. سيقودك النظام إلى البيانات المطلوبة دون عرض خطوات تقنية غير ضرورية.</p></div><Badge className="bg-[#e8f3eb] text-[#1d634c] hover:bg-[#e8f3eb]">{status.data.percent}% مكتمل</Badge></div><Progress value={status.data.percent} className="mt-2 h-2" /></CardHeader><CardContent className="flex flex-wrap items-center justify-between gap-3 pt-0"><div className="flex flex-wrap gap-2 text-xs text-[#587064]">{status.data.steps.filter((step) => !step.complete).slice(0, 3).map((step) => <span key={step.code} className="rounded-full bg-white px-3 py-1.5">{step.label}</span>)}</div><Button className="bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => navigate("/settings")}>متابعة الإعداد</Button></CardContent></Card>;
}

function CeoAssistantCoordinationNotice() {
  return <Card className="border-0 bg-white shadow-sm" dir="rtl"><CardHeader><CardTitle className="text-base text-[#18332f]">مركز تنسيق مكتب الرئيس التنفيذي</CardTitle></CardHeader><CardContent className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#f1f6f2] p-4"><p className="font-semibold text-[#0b3d3a]">متابعة وتوجيه</p><p className="mt-1 text-sm leading-6 text-[#64716a]">تجميع التكليفات ومتابعة الخطوات التالية مع الإدارات.</p></div><div className="rounded-xl bg-[#f7f3e8] p-4"><p className="font-semibold text-[#765a19]">تنبيهات تحتاج قراراً</p><p className="mt-1 text-sm leading-6 text-[#64716a]">رفع البنود المهمة للرئيس التنفيذي دون اعتمادها نيابةً عنه.</p></div><div className="rounded-xl bg-[#eef2f7] p-4"><p className="font-semibold text-[#31557e]">حدود الدور</p><p className="mt-1 text-sm leading-6 text-[#64716a]">لا توجد صلاحية للمحاسبة أو الفواتير أو المدفوعات أو إدارة المستخدمين.</p></div></CardContent></Card>;
}

function ExecutiveDashboard({ isLoading, hasWorkspace, tenantId, companyId }: { isLoading: boolean; hasWorkspace: boolean; tenantId?: number; companyId?: number }) {
  const balance = trpc.operations.trialBalance.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled: Boolean(tenantId && companyId) });
  const totals = (balance.data ?? []).reduce((result, row) => { const debit = Number(row.debit); const credit = Number(row.credit); if (row.accountType === "revenue") result.revenue += credit - debit; if (row.accountType === "expense" || row.accountType === "cost_of_revenue") result.expenses += debit - credit; if (row.accountType === "asset") result.assets += debit - credit; if (row.accountType === "liability") result.liabilities += credit - debit; return result; }, { revenue: 0, expenses: 0, assets: 0, liabilities: 0 });
  const metrics = [
    { label: "الإيرادات", icon: TrendingUp, tone: "bg-[#e9f4ed] text-[#1b6843]", value: totals.revenue },
    { label: "صافي النتيجة", icon: BarChart3, tone: "bg-[#e8f0f6] text-[#215b7f]", value: totals.revenue - totals.expenses },
    { label: "الأصول", icon: WalletCards, tone: "bg-[#fbf2df] text-[#946517]", value: totals.assets },
    { label: "الالتزامات", icon: CircleDollarSign, tone: "bg-[#f7ebed] text-[#993e4c]", value: totals.liabilities },
  ];
  return <>
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      {metrics.map(({ label, icon: Icon, tone, value }) => <Card key={label} className="border-0 shadow-sm bg-white rounded-2xl">
        <CardContent className="p-5">
          <div className="flex items-center justify-between"><div className={`h-10 w-10 rounded-xl flex items-center justify-center ${tone}`}><Icon className="h-5 w-5" /></div><Badge variant="outline" className="text-[10px] border-[#e5e9e5]">دفتر الأستاذ</Badge></div>
          <p className="mt-5 text-sm text-[#6e7973]">{label}</p><p className="mt-1 text-2xl font-bold text-[#172d2b]" dir="ltr">{isLoading || balance.isLoading ? "…" : hasWorkspace ? formatMoney(value.toFixed(6)) : "—"}</p>
          <p className="mt-2 text-xs text-[#8a948e]">{hasWorkspace ? balance.data?.length ? "من القيود المرحلة" : "لا توجد عمليات مرحلة حتى الآن" : "أكمل إعداد الشركة لإظهار البيانات"}</p>
        </CardContent>
      </Card>)}
    </section>
    <section className="grid gap-5 xl:grid-cols-[1.45fr_0.8fr]">
      <Card className="border-0 shadow-sm rounded-2xl"><CardHeader className="pb-2"><div className="flex items-center justify-between"><div><CardTitle className="text-base text-[#18332f]">مسار الإقفال الشهري</CardTitle><p className="mt-1 text-sm text-muted-foreground">متابعة الضوابط قبل إغلاق الفترة.</p></div><Badge className="bg-[#f1f4ef] text-[#5c6c62] hover:bg-[#f1f4ef]">بانتظار التهيئة</Badge></div></CardHeader><CardContent className="space-y-4 p-6 pt-3"><Progress value={0} className="h-2 bg-[#edf1ec]" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{["مطابقة البنوك", "مراجعة العملاء", "VAT", "ميزان المراجعة"].map((item) => <div key={item} className="rounded-xl border border-dashed border-[#dde4de] p-3 text-center text-xs text-[#64716a]">{item}</div>)}</div><p className="text-xs leading-5 text-[#7c8781]">تظهر نسبة التقدم من مهام فعلية وقيود مرحلة فقط، ولا تعرض المنصة قيماً تجريبية كمؤشرات مالية.</p></CardContent></Card>
      <Card className="border-0 shadow-sm rounded-2xl bg-[#103d3a] text-white"><CardContent className="p-6"><div className="flex items-center gap-3"><div className="h-10 w-10 rounded-xl bg-white/10 flex items-center justify-center"><Sparkles className="h-5 w-5" /></div><div><p className="font-semibold">المساعد المالي الذكي</p><p className="text-xs text-white/65">مقيد بالأدوار ومصادر البيانات</p></div></div><p className="mt-6 text-sm leading-7 text-white/82">سيحلل المساعد البيانات المرحلة ويعرض الفترة والمصدر والقيود المستخدمة. لا ينفّذ قيوداً ولا اعتمادات تلقائياً.</p><Button variant="secondary" className="mt-5 w-full bg-white text-[#0b3d3a] hover:bg-[#eef5f0]" onClick={() => toast.info("يُفعّل المساعد بعد توصيل طبقة البيانات والتفويض التفصيلي.")}>عرض ضوابط المساعد <Bot className="mr-2 h-4 w-4" /></Button></CardContent></Card>
    </section>
    <Card className="border-0 shadow-sm rounded-2xl"><CardContent className="flex flex-col gap-4 p-6 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><div className="h-10 w-10 shrink-0 rounded-xl bg-[#fff4e3] text-[#a46612] flex items-center justify-center"><AlertCircle className="h-5 w-5" /></div><div><p className="font-semibold text-[#31433b]">تنبيه تشغيل</p><p className="mt-1 text-sm text-[#6b766f]">ابدأ بتهيئة الشركة، دليل الحسابات، والفترة المالية قبل إصدار المستندات أو ترحيلها.</p></div></div><Button className="bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => window.location.assign("/settings")}>تهيئة الشركة <ArrowLeft className="mr-2 h-4 w-4" /></Button></CardContent></Card>
    <FinancialCopilot tenantId={tenantId} companyId={companyId} />
  </>;
}

function FinancialCopilot({ tenantId, companyId }: { tenantId?: number; companyId?: number }) {
  const [messages, setMessages] = useState<AIMessage[]>([]); const ask = trpc.assistant.ask.useMutation({ onSuccess: (result) => setMessages((previous) => [...previous, { role: "assistant", content: `${result.answer}\n\n> المصدر: ${result.sourceLabel} — ${result.entryCount} حسابات مرصودة. الفترة: ${result.periodStart && result.periodEnd ? `${result.periodStart} إلى ${result.periodEnd}` : "لا توجد فترة مصدرية كافية"}.` }]), onError: (error) => { toast.error(error.message); setMessages((previous) => previous.slice(0, -1)); } });
  const onSend = (question: string) => { if (!tenantId || !companyId) { toast.info("أكمل إعداد مساحة العمل أولاً."); return; } setMessages((previous) => [...previous, { role: "user", content: question }]); ask.mutate({ tenantId, companyId, question }); };
  return <Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">اسأل المساعد المالي</CardTitle><p className="text-sm text-muted-foreground">قراءة تفسيرية فقط لقيود الشركة المرحلة؛ لا ينفذ المساعد أي ترحيل أو اعتماد أو إرسال ضريبي.</p></CardHeader><CardContent><AIChatBox messages={messages} onSendMessage={onSend} isLoading={ask.isPending} height="360px" placeholder="مثال: ما الحسابات التي تحتوي على حركة مرحلة؟" emptyStateMessage="اطرح سؤالاً عن القيود المرحلة وميزان المراجعة." suggestedPrompts={["هل توجد حركة مرحلة في الإيرادات؟", "ما الحسابات التي لها أرصدة مدينة؟"]} /></CardContent></Card>;
}

function normalizeIsoDate(value: string) { const digits = value.replace(/\D/g, ""); if (/^\d{8}$/.test(digits)) return `${digits.slice(0, 4)}-${digits.slice(4, 6)}-${digits.slice(6, 8)}`; return /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : ""; }

function SalesQuickActions() {
  const goTo = (id: string) => document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
  return <Card className="rounded-2xl border-0 bg-[#103d3a] text-white shadow-sm" dir="rtl"><CardContent className="p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold tracking-[0.16em] text-white/60">SALES DESK</p><h2 className="mt-1 text-xl font-bold">إجراءات قسم المبيعات</h2><p className="mt-1 text-sm text-white/75">ابدأ من العميل أو أنشئ عرض سعر جديداً، أما الفواتير فلها قسم مستقل.</p></div><div className="grid w-full gap-3 sm:w-auto sm:min-w-[520px] sm:grid-cols-2"><Button type="button" onClick={() => goTo("sales-customer-actions")} className="h-12 justify-start bg-white text-[#0b3d3a] hover:bg-[#eef5f0]"><UsersRound className="ml-2 h-5 w-5" />عميل وجهة اتصال جديدة</Button><Button type="button" onClick={() => goTo("sales-document-actions")} className="h-12 justify-start border border-white/30 bg-white/10 text-white hover:bg-white/20"><FilePlus2 className="ml-2 h-5 w-5" />إنشاء عرض سعر</Button></div></div></CardContent></Card>;
}

function SalesWorkbench({ tenantId, companyId, roleCode }: { tenantId?: number; companyId?: number; roleCode?: string }) {
  if (roleCode === "sales_rep") return <SalesRepWorkspace tenantId={tenantId} companyId={companyId} />;
  if (roleCode === "sales") return <><SalesSupervisorWorkspace tenantId={tenantId} companyId={companyId} /><SalesCRMBoard tenantId={tenantId} companyId={companyId} roleCode={roleCode} /><SalesPerformanceReports tenantId={tenantId} companyId={companyId} roleCode={roleCode} /><SalesRepOwnershipBoard tenantId={tenantId} companyId={companyId} /><CustomerRelationshipManager tenantId={tenantId} companyId={companyId} /></>;
  const isMonitor = roleCode === "ceo_assistant";
  const [newCustomerId, setNewCustomerId] = useState<number>();
  return <>{!isMonitor && <><SalesQuickActions /><div id="sales-customer-actions" className="scroll-mt-6"><SalesOperations tenantId={tenantId} companyId={companyId} onCustomerCreated={(customerId) => { setNewCustomerId(customerId); window.setTimeout(() => document.getElementById("sales-document-actions")?.scrollIntoView({ behavior: "smooth", block: "start" }), 80); }} /></div><div id="sales-document-actions" className="scroll-mt-6"><QuotationWorkflow tenantId={tenantId} companyId={companyId} initialCustomerId={newCustomerId} /></div></>}<SalesCRMBoard tenantId={tenantId} companyId={companyId} roleCode={roleCode} /><SalesRepDashboard tenantId={tenantId} companyId={companyId} /><SalesPerformanceReports tenantId={tenantId} companyId={companyId} roleCode={roleCode} />{!isMonitor && <><SalesRepOwnershipBoard tenantId={tenantId} companyId={companyId} /><SalesCatalogQuickAdd tenantId={tenantId} companyId={companyId} /><CustomerRelationshipManager tenantId={tenantId} companyId={companyId} /></>}</>
}

function BillingWorkbench({ tenantId, companyId, roleCode }: { tenantId?: number; companyId?: number; roleCode?: string }) {
  return <><PriceOnRequestDocumentForm tenantId={tenantId} companyId={companyId} mode="invoice" /><SalesSupervisorInvoiceBoard tenantId={tenantId} companyId={companyId} roleCode={roleCode} /><CollectionsBoard tenantId={tenantId} companyId={companyId} /><OfficialDocumentsIndex tenantId={tenantId} companyId={companyId} roleCode={roleCode} /></>;
}

function SalesSupervisorInvoiceBoard({ tenantId, companyId, roleCode }: { tenantId?: number; companyId?: number; roleCode?: string }) {
  const enabled = roleCode === "sales" && Boolean(tenantId && companyId);
  const invoicesQuery = trpc.sales.listInvoices.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  if (!enabled) return null;
  const exportInvoices = () => {
    const blob = new Blob([buildSalesSupervisorInvoiceCsv(invoicesQuery.data ?? [])], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "sales-supervisor-invoices.csv"; anchor.click(); URL.revokeObjectURL(url);
  };
  return <Card className="rounded-2xl border-0 shadow-sm" dir="rtl"><CardHeader className="flex flex-row items-center justify-between gap-3"><div><CardTitle className="flex items-center gap-2 text-base"><FileText className="h-5 w-5 text-[#0b3d3a]" />فواتير فريق المبيعات</CardTitle><p className="mt-1 text-sm text-muted-foreground">فواتير عروض الأسعار التي أنشأها ممثلو المبيعات، للمتابعة والتصدير.</p></div><Button variant="outline" onClick={exportInvoices} disabled={!invoicesQuery.data?.length}><Download className="ml-2 h-4 w-4" />تصدير الفواتير</Button></CardHeader><CardContent>{invoicesQuery.isLoading ? <p className="text-sm text-muted-foreground">جارٍ تحميل فواتير الفريق...</p> : invoicesQuery.error ? <p className="rounded-xl bg-[#fff1ee] p-4 text-sm text-[#9a3e32]">تعذر تحميل فواتير الفريق: {invoicesQuery.error.message}</p> : invoicesQuery.data?.length ? <div className="space-y-2">{invoicesQuery.data.map((invoice) => <div key={invoice.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#e2e9e3] p-3"><div><p className="font-semibold">{invoice.invoiceNumber}</p><p className="text-xs text-muted-foreground">{invoice.status} · {new Date(invoice.issueDate).toISOString().slice(0, 10)}</p></div><p className="font-semibold" dir="ltr">SAR {Number(invoice.grandTotal).toFixed(2)}</p></div>)}</div> : <p className="rounded-xl border border-dashed p-6 text-center text-sm text-muted-foreground">لا توجد فواتير منشأة من عروض فريق المبيعات.</p>}</CardContent></Card>;
}

function SalesOperations({ tenantId, companyId, onCustomerCreated }: { tenantId?: number; companyId?: number; onCustomerCreated?: (customerId: number) => void }) {
  const enabled = Boolean(tenantId && companyId);
  const customers = trpc.sales.listCustomers.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  const services = trpc.sales.listServices.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  const assignees = trpc.sales.listSalesAssignees.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  const [customerName, setCustomerName] = useState(""); const [customerType, setCustomerType] = useState<"individual" | "company" | "government">("company"); const [customerUnifiedNumber, setCustomerUnifiedNumber] = useState(""); const [customerVatNumber, setCustomerVatNumber] = useState(""); const [salesOwnerUserId, setSalesOwnerUserId] = useState(""); const [accountTier, setAccountTier] = useState<"standard" | "large" | "strategic">("standard"); const [contactName, setContactName] = useState(""); const [contactTitle, setContactTitle] = useState(""); const [contactEmail, setContactEmail] = useState(""); const [contactPhone, setContactPhone] = useState(""); const [serviceName, setServiceName] = useState(""); const [servicePrice, setServicePrice] = useState("");
  const [selectedCustomer, setSelectedCustomer] = useState(""); const [selectedService, setSelectedService] = useState(""); const [actualInvoiceNumber, setActualInvoiceNumber] = useState("");
  const createCustomer = trpc.sales.createCustomer.useMutation({ onSuccess: (result) => { onCustomerCreated?.(result.id); toast.success("تم إنشاء العميل وجهة الاتصال الأساسية."); setCustomerName(""); setCustomerType("company"); setCustomerUnifiedNumber(""); setCustomerVatNumber(""); setSalesOwnerUserId(""); setAccountTier("standard"); setContactName(""); setContactTitle(""); setContactEmail(""); setContactPhone(""); customers.refetch(); }, onError: (error) => toast.error(error.message) });
  const createService = trpc.sales.createService.useMutation({ onSuccess: () => { toast.success("تم إنشاء الخدمة."); setServiceName(""); setServicePrice(""); services.refetch(); } });
  const issue = trpc.sales.createAndIssueInvoice.useMutation({ onSuccess: (result) => { toast.success(`صدرت الفاتورة وأنشئ القيد ${result.journalEntryId}.`); setActualInvoiceNumber(""); }, onError: (error) => toast.error(error.message) });
  if (!enabled) return <Card className="mt-5 border-0 shadow-sm rounded-2xl"><CardContent className="p-6"><Empty icon={Building2} title="أنشئ مساحة عمل أولاً" description="بعد تهيئة الشركة، ستتمكن من إنشاء عميل وخدمة وإصدار فاتورة مرتبطة بقيد محاسبي." /></CardContent></Card>;
  const service = services.data?.find((item) => String(item.id) === selectedService); const isIndividual = customerType === "individual"; const vatFormatValid = isIndividual ? true : /^\d{15}$/.test(customerVatNumber); const unifiedFormatValid = isIndividual ? true : /^\d{10}$/.test(customerUnifiedNumber); const companyIdentityValid = isIndividual || (vatFormatValid && unifiedFormatValid);
  return <section className="mt-5 grid gap-5 xl:grid-cols-3"><Card className="border-0 shadow-sm rounded-2xl xl:col-span-2" id="sales-unified-customer-form"><CardHeader><CardTitle className="text-base">عميل وجهة اتصال جديدة</CardTitle><p className="text-sm text-muted-foreground">أدخل بيانات المنشأة وجهة الاتصال الأساسية في نموذج واحد؛ سيتم ربطهما تلقائياً.</p></CardHeader><CardContent className="space-y-4"><div className="rounded-xl bg-[#f7f9f7] p-4"><p className="mb-3 text-sm font-semibold text-[#34473d]">بيانات العميل أو المنشأة</p><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm font-medium text-[#44564d]">نوع العميل<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={customerType} onChange={(event) => setCustomerType(event.target.value as typeof customerType)}><option value="company">شركة</option><option value="government">جهة حكومية</option><option value="individual">فرد / طالب خدمة</option></select></label><Field label="اسم العميل أو المنشأة *" value={customerName} onChange={setCustomerName} placeholder={isIndividual ? "اسم طالب الخدمة" : "اسم الشركة"} /><Field label="الرقم الموحد" value={customerUnifiedNumber} onChange={setCustomerUnifiedNumber} placeholder={isIndividual ? "غير مطلوب للفرد" : "10 أرقام"} dir="ltr" inputMode="numeric" disabled={isIndividual} /><Field label="الرقم الضريبي" value={customerVatNumber} onChange={setCustomerVatNumber} placeholder={isIndividual ? "غير مطلوب للفرد" : "15 رقماً"} dir="ltr" inputMode="numeric" disabled={isIndividual} />{!isIndividual && customerVatNumber && <p className={`sm:col-span-2 text-xs ${vatFormatValid && unifiedFormatValid ? "text-[#177245]" : "text-[#9a3e32]"}`}>{vatFormatValid && unifiedFormatValid ? "الرقم الضريبي والرقم الموحد صالحان." : "للشركة: الرقم الضريبي يجب أن يكون 15 رقماً والرقم الموحد 10 أرقام."}</p>}<label className="text-sm font-medium text-[#44564d]">ممثل المبيعات<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={salesOwnerUserId} onChange={(event) => setSalesOwnerUserId(event.target.value)}><option value="">غير معين</option>{assignees.data?.map((member) => <option key={member.userId} value={member.userId}>{member.name || member.email || `موظف #${member.userId}`}</option>)}</select></label><label className="text-sm font-medium text-[#44564d]">طبقة الحساب<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={accountTier} onChange={(event) => setAccountTier(event.target.value as typeof accountTier)}><option value="standard">عادي</option><option value="large">شركة كبرى</option><option value="strategic">حساب استراتيجي</option></select></label></div></div><div className="rounded-xl bg-[#f7f9f7] p-4"><p className="mb-3 text-sm font-semibold text-[#34473d]">جهة الاتصال الأساسية</p><div className="grid gap-3 sm:grid-cols-2"><Field label="اسم المسؤول *" value={contactName} onChange={setContactName} placeholder="اسم الشخص المسؤول" /><Field label="المسمى الوظيفي" value={contactTitle} onChange={setContactTitle} placeholder="المدير المالي" /><Field label="البريد الإلكتروني" value={contactEmail} onChange={setContactEmail} placeholder="contact@company.com" dir="ltr" /><Field label="رقم الجوال" value={contactPhone} onChange={setContactPhone} placeholder="05xxxxxxxx" dir="ltr" /></div></div><Button disabled={!customerName.trim() || !contactName.trim() || !companyIdentityValid || createCustomer.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => createCustomer.mutate({ tenantId: tenantId!, companyId: companyId!, name: customerName.trim(), customerType, unifiedNumber: customerUnifiedNumber.trim() || undefined, vatNumber: customerVatNumber.trim() || undefined, salesOwnerUserId: salesOwnerUserId ? Number(salesOwnerUserId) : undefined, accountTier, primaryContactName: contactName.trim(), primaryContactTitle: contactTitle.trim() || undefined, primaryContactEmail: contactEmail.trim() || undefined, primaryContactPhone: contactPhone.trim() || undefined })}>{createCustomer.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}حفظ العميل وجهة الاتصال</Button><p className="text-xs text-muted-foreground">{customers.data?.length ?? 0} عملاء نشطين · تُسجل جهة الاتصال كجهة أساسية قابلة للتعديل لاحقاً.</p></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">خدمة جديدة</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="اسم الخدمة" value={serviceName} onChange={setServiceName} /><Field label="السعر" value={servicePrice} onChange={setServicePrice} inputMode="decimal" dir="ltr" /><Button disabled={!serviceName || !servicePrice || createService.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => createService.mutate({ tenantId: tenantId!, companyId: companyId!, nameAr: serviceName, unitPrice: servicePrice })}>إضافة خدمة</Button><p className="text-xs text-muted-foreground">{services.data?.length ?? 0} خدمات نشطة</p></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">إصدار فاتورة وقيد</CardTitle></CardHeader><CardContent className="space-y-3"><label className="text-sm font-medium text-[#44564d]">العميل<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={selectedCustomer} onChange={(event) => setSelectedCustomer(event.target.value)}><option value="">اختر العميل</option>{customers.data?.map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></label><label className="text-sm font-medium text-[#44564d]">الخدمة<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={selectedService} onChange={(event) => setSelectedService(event.target.value)}><option value="">اختر الخدمة</option>{services.data?.map((item) => <option key={item.id} value={item.id}>{item.nameAr}</option>)}</select></label><Field label="رقم الفاتورة" value={actualInvoiceNumber} onChange={setActualInvoiceNumber} placeholder="INV-2026-000001" dir="ltr" /><Button disabled={!selectedCustomer || !service || !actualInvoiceNumber || issue.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => issue.mutate({ tenantId: tenantId!, companyId: companyId!, customerId: Number(selectedCustomer), invoiceNumber: actualInvoiceNumber, invoiceType: "standard", issueDate: new Date().toISOString().slice(0, 10), lines: [{ productServiceId: service!.id, description: service!.nameAr, quantity: "1", unitPrice: service!.unitPrice, discountAmount: "0", taxRateBps: 1500 }] })}>{issue.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}إصدار وترحيل</Button></CardContent></Card></section>;
}

function QuotationWorkflow({ tenantId, companyId, initialCustomerId }: { tenantId?: number; companyId?: number; initialCustomerId?: number }) { const enabled = Boolean(tenantId && companyId); const customers = trpc.sales.listCustomers.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const services = trpc.sales.listServices.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const quotes = trpc.sales.listQuotations.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const [customerId, setCustomerId] = useState(initialCustomerId ? String(initialCustomerId) : ""); useEffect(() => { if (initialCustomerId) setCustomerId(String(initialCustomerId)); }, [initialCustomerId]); const [serviceId, setServiceId] = useState(""); const [quoteNumber, setQuoteNumber] = useState(""); const [convertNumber, setConvertNumber] = useState(""); const service = services.data?.find((item) => String(item.id) === serviceId); const servicePriceValid = Boolean(service && isValidOnRequestPrice(service.unitPrice)); const create = trpc.sales.createQuotation.useMutation({ onSuccess: () => { toast.success("تم حفظ عرض السعر."); quotes.refetch(); setQuoteNumber(""); }, onError: (e) => toast.error(e.message) }); const convert = trpc.sales.convertQuotationToDraft.useMutation({ onSuccess: (result) => { toast.success(`حُوّل العرض إلى فاتورة مسودة ${result.invoiceId}.`); quotes.refetch(); }, onError: (e) => toast.error(e.message) }); if (!enabled) return null; return <section className="mt-5 grid gap-5 xl:grid-cols-[0.9fr_1.1fr]"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">عرض سعر جديد</CardTitle></CardHeader><CardContent className="space-y-3"><label className="text-sm font-medium text-[#44564d]">العميل<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={customerId} onChange={(event) => setCustomerId(event.target.value)}><option value="">اختر العميل</option>{customers.data?.map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></label><label className="text-sm font-medium text-[#44564d]">الخدمة<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={serviceId} onChange={(event) => setServiceId(event.target.value)}><option value="">اختر الخدمة</option>{services.data?.map((item) => <option key={item.id} value={item.id}>{item.nameAr}</option>)}</select></label>{service && !servicePriceValid && <p className="rounded-lg bg-[#fff3e8] p-3 text-xs leading-5 text-[#9a3e32]">لا يمكن إنشاء عرض سعر لهذه الخدمة حالياً لأن سعرها غير محدد. أضف السعر من كتالوج الخدمات أولاً.</p>}<div className="rounded-lg border border-dashed border-[#b9cdbd] bg-[#f7f9f7] p-3 text-sm"><span className="font-medium text-[#34473d]">رقم العرض</span><span className="mr-2 text-muted-foreground" dir="ltr">يُولّد تلقائياً عند الحفظ وفق التسلسل المعتمد</span></div><Button className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={!customerId || !servicePriceValid || create.isPending} onClick={() => create.mutate({ tenantId: tenantId!, companyId: companyId!, customerId: Number(customerId), issueDate: new Date().toISOString().slice(0, 10), lines: [{ productServiceId: service!.id, description: service!.nameAr, quantity: "1", unitPrice: service!.unitPrice, discountAmount: "0", taxRateBps: 1500 }] })}>حفظ العرض برقم تلقائي</Button></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">تحويل العروض</CardTitle><p className="text-sm text-muted-foreground">ينشئ التحويل فاتورة مسودة مرتبطة بالعرض؛ يظل الإصدار والترحيل مرحلة منفصلة ومضبوطة.</p></CardHeader><CardContent className="space-y-3"><Field label="رقم الفاتورة الجديدة" value={convertNumber} onChange={setConvertNumber} placeholder="INV-2026-000001" dir="ltr" />{quotes.data?.length ? quotes.data.map((quote) => <div key={quote.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#e4e9e4] p-3"><div><p className="font-medium" dir="ltr">{quote.quoteNumber}</p><p className="mt-1 text-xs text-muted-foreground">{quote.status} · {formatMoney(quote.grandTotal)}</p></div><Button size="sm" variant="outline" disabled={quote.status === "converted" || !convertNumber || convert.isPending} onClick={() => convert.mutate({ tenantId: tenantId!, companyId: companyId!, quotationId: quote.id, invoiceNumber: convertNumber, issueDate: new Date().toISOString().slice(0, 10), invoiceType: "standard" })}>تحويل إلى مسودة</Button></div>) : <Empty icon={ReceiptText} title="لا توجد عروض أسعار" description="أنشئ عرضاً مرتبطاً بعميل وخدمة ليظهر هنا." />}</CardContent></Card></section>; }

function InvoicePreview({ result }: { result: ReturnType<typeof trpc.finance.previewInvoice.useMutation>["data"] }) {
  return <Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">نتيجة الفحص</CardTitle></CardHeader><CardContent className="space-y-5">{!result ? <div className="rounded-xl border border-dashed border-[#dce4dd] p-7 text-center"><ShieldCheck className="mx-auto h-8 w-8 text-[#8ba398]" /><p className="mt-3 font-medium text-[#405149]">بانتظار إدخال مستند</p><p className="mt-1 text-sm leading-6 text-muted-foreground">ستظهر المجاميع ودرجة الفحص بعد التنفيذ. لا يتم حفظ أو إرسال أي فاتورة من هذه المعاينة.</p></div> : <><div className={`rounded-xl p-4 ${result.compliance.canIssue ? "bg-[#eaf5ed]" : "bg-[#fff3e8]"}`}><div className="flex items-center justify-between"><div><p className="font-bold text-[#264135]">درجة الفحص البنيوي</p><p className="mt-1 text-sm text-[#587064]">{result.compliance.canIssue ? "لا توجد أخطاء حرجة في الفحص الحالي" : "توجد عناصر حرجة تمنع الإصدار"}</p></div><span className="text-3xl font-bold text-[#0b3d3a]" dir="ltr">{result.compliance.score}/100</span></div></div><div className="space-y-3">{[["الإجمالي قبل الخصم", result.totals.subtotal], ["الخصومات", result.totals.discountTotal], ["الضريبة", result.totals.taxTotal], ["إجمالي الفاتورة", result.totals.grandTotal]].map(([label, value]) => <div key={label as string} className="flex items-center justify-between text-sm"><span className="text-muted-foreground">{label}</span><span className="font-semibold text-[#1c3833]" dir="ltr">{formatMoney(value as string)}</span></div>)}</div><Separator />{result.compliance.issues.length === 0 ? <div className="flex gap-2 text-sm text-[#197044]"><CheckCircle2 className="h-5 w-5 shrink-0" />الفحص البنيوي مكتمل، مع بقاء تحقق قواعد الامتثال النشطة والتفويض قبل الإصدار.</div> : <div className="space-y-2">{result.compliance.issues.map((issue) => <div className="flex gap-2 text-sm text-[#a75a1d]" key={issue.code}><AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />{issue.message}</div>)}</div>}<p className="text-xs leading-5 text-muted-foreground">{result.compliance.notice}</p></>}</CardContent></Card>;
}

function AccountingWorkbench({ tenantId, companyId }: { tenantId?: number; companyId?: number }) {
  const [debitOne, setDebitOne] = useState("0"); const [creditOne, setCreditOne] = useState("0"); const [debitTwo, setDebitTwo] = useState("0"); const [creditTwo, setCreditTwo] = useState("0");
  const validate = trpc.finance.validateJournal.useMutation();
  const result = validate.data;
  return <><section className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><div className="flex gap-3"><div className="h-10 w-10 rounded-xl bg-[#e8f0f6] text-[#285c7d] flex items-center justify-center"><BookOpenCheck className="h-5 w-5" /></div><div><CardTitle className="text-base">فاحص توازن القيد</CardTitle><p className="mt-1 text-sm text-muted-foreground">لا يُسمح بترحيل قيد إذا اختلف مجموع المدين عن الدائن.</p></div></div></CardHeader><CardContent className="space-y-4"><div className="rounded-xl border border-[#e8ece7] overflow-hidden"><div className="grid grid-cols-2 bg-[#f6f8f5] px-4 py-3 text-xs font-bold text-[#587064]"><span>مدين</span><span>دائن</span></div><div className="grid grid-cols-2 gap-3 p-4"><Input dir="ltr" value={debitOne} onChange={(e) => setDebitOne(e.target.value)} inputMode="decimal" /><Input dir="ltr" value={creditOne} onChange={(e) => setCreditOne(e.target.value)} inputMode="decimal" /><Input dir="ltr" value={debitTwo} onChange={(e) => setDebitTwo(e.target.value)} inputMode="decimal" /><Input dir="ltr" value={creditTwo} onChange={(e) => setCreditTwo(e.target.value)} inputMode="decimal" /></div></div><Button className="bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={validate.isPending} onClick={() => validate.mutate({ lines: [{ debit: debitOne, credit: creditOne }, { debit: debitTwo, credit: creditTwo }] })}>{validate.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}التحقق من التوازن</Button></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">نتيجة سلامة القيد</CardTitle></CardHeader><CardContent>{!result ? <Empty icon={Landmark} title="لم يُفحص قيد بعد" description="أدخل قيم المدين والدائن، ثم نفّذ الفحص الحتمي في الخادم." /> : <div className={`rounded-2xl p-5 ${result.valid ? "bg-[#eaf5ed]" : "bg-[#fff3e8]"}`}><div className="flex items-center gap-2 font-bold text-[#244035]">{result.valid ? <CheckCircle2 className="h-5 w-5 text-[#168045]" /> : <AlertCircle className="h-5 w-5 text-[#b36420]" />}{result.message}</div><Separator className="my-4 bg-black/5" /><div className="grid grid-cols-2 gap-3 text-sm"><div><p className="text-muted-foreground">مجموع المدين</p><p className="mt-1 font-bold" dir="ltr">{formatMoney(result.debitTotal)}</p></div><div><p className="text-muted-foreground">مجموع الدائن</p><p className="mt-1 font-bold" dir="ltr">{formatMoney(result.creditTotal)}</p></div></div></div>}</CardContent></Card></section><TrialBalance tenantId={tenantId} companyId={companyId} /><FinancialStatementCards tenantId={tenantId} companyId={companyId} /><ChartOfAccounts tenantId={tenantId} companyId={companyId} /></>;
}

function TrialBalance({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const report = trpc.operations.trialBalance.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled: Boolean(tenantId && companyId) }); if (!tenantId || !companyId) return null; return <Card className="mt-5 overflow-hidden border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">ميزان المراجعة</CardTitle><p className="text-sm text-muted-foreground">يُحتسب من القيود ذات الحالة المرحلة فقط.</p></CardHeader><CardContent>{report.isLoading ? <Loader2 className="h-5 w-5 animate-spin text-[#0b3d3a]" /> : report.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[560px] text-right text-sm"><thead className="border-b text-xs text-muted-foreground"><tr><th className="p-3">الحساب</th><th className="p-3">النوع</th><th className="p-3">مدين</th><th className="p-3">دائن</th></tr></thead><tbody>{report.data.map((row) => <tr key={row.code} className="border-b last:border-0"><td className="p-3 font-medium">{row.nameAr} <span className="text-xs text-muted-foreground" dir="ltr">{row.code}</span></td><td className="p-3 text-muted-foreground">{row.accountType}</td><td className="p-3" dir="ltr">{formatMoney(row.debit)}</td><td className="p-3" dir="ltr">{formatMoney(row.credit)}</td></tr>)}</tbody></table></div> : <Empty icon={BookOpenCheck} title="لا توجد قيود مرحلة" description="سيظهر ميزان المراجعة فور إصدار فاتورة أو تسجيل قيد مُرحّل." />}</CardContent></Card>; }

function FinancialStatementCards({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const report = trpc.operations.trialBalance.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled: Boolean(tenantId && companyId) }); if (!tenantId || !companyId || !report.data?.length) return null; const totals = report.data.reduce((result, row) => { const debit = Number(row.debit); const credit = Number(row.credit); if (row.accountType === "revenue") result.revenue += credit - debit; if (row.accountType === "expense" || row.accountType === "cost_of_revenue") result.expenses += debit - credit; if (row.accountType === "asset") result.assets += debit - credit; if (row.accountType === "liability" || row.accountType === "equity") result.liabilitiesEquity += credit - debit; return result; }, { revenue: 0, expenses: 0, assets: 0, liabilitiesEquity: 0 }); return <section className="mt-5 grid gap-5 sm:grid-cols-2"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">قائمة الدخل المختصرة</CardTitle></CardHeader><CardContent className="space-y-3 text-sm"><div className="flex justify-between"><span>الإيرادات</span><span dir="ltr">{formatMoney(totals.revenue.toFixed(6))}</span></div><div className="flex justify-between"><span>التكاليف والمصروفات</span><span dir="ltr">{formatMoney(totals.expenses.toFixed(6))}</span></div><Separator /><div className="flex justify-between font-bold text-[#0b3d3a]"><span>صافي النتيجة</span><span dir="ltr">{formatMoney((totals.revenue - totals.expenses).toFixed(6))}</span></div></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">المركز المالي المختصر</CardTitle></CardHeader><CardContent className="space-y-3 text-sm"><div className="flex justify-between"><span>الأصول</span><span dir="ltr">{formatMoney(totals.assets.toFixed(6))}</span></div><div className="flex justify-between"><span>الالتزامات وحقوق الملكية</span><span dir="ltr">{formatMoney(totals.liabilitiesEquity.toFixed(6))}</span></div><p className="pt-2 text-xs leading-5 text-muted-foreground">يعرض الملخص الأرصدة المتاحة في ميزان المراجعة، ويستلزم مراجعة محاسب مؤهل قبل استخدامه كقائمة نظامية.</p></CardContent></Card></section>; }

function ChartOfAccounts({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const chart = trpc.finance.chartOfAccounts.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled: Boolean(tenantId && companyId) }); if (!tenantId || !companyId) return null; const byId = new Map((chart.data ?? []).map((account) => [account.id, account])); const levelFor = (accountId: number, seen = new Set<number>()): number => { const account = byId.get(accountId); if (!account?.parentId || seen.has(accountId)) return 0; seen.add(accountId); return 1 + levelFor(account.parentId, seen); }; return <Card className="mt-5 overflow-hidden border-0 shadow-sm rounded-2xl"><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle className="text-base">دليل الحسابات الهرمي</CardTitle><p className="mt-1 text-sm text-muted-foreground">يبين المستوى وعلاقة الحساب الأب وحالة الترحيل. القيود المرحلة غير قابلة للتعديل عبر إجراءات المنصة.</p></div>{chart.data?.length ? <Badge variant="outline" className="text-[#527062]">{chart.data.length} حساب</Badge> : null}</div></CardHeader><CardContent>{chart.isLoading ? <Loader2 className="h-5 w-5 animate-spin text-[#0b3d3a]" /> : chart.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-right text-sm"><thead className="border-b text-xs text-muted-foreground"><tr><th className="p-3">الكود</th><th className="p-3">الحساب</th><th className="p-3">الأب</th><th className="p-3">النوع</th><th className="p-3">الترحيل</th></tr></thead><tbody>{chart.data.map((account) => { const level = levelFor(account.id); const parent = account.parentId ? byId.get(account.parentId) : undefined; return <tr key={account.id} className="border-b last:border-0"><td className="p-3" dir="ltr">{account.code}</td><td className="p-3 font-medium"><div className="flex items-center gap-2" style={{ paddingInlineStart: `${level * 1.25}rem` }}>{level > 0 ? <span className="text-[#8aa096]">↳</span> : <span className="h-4 w-4 rounded-full border border-[#dce6de] bg-[#f5f8f5]" />}{account.nameAr}<span className="text-xs font-normal text-muted-foreground">المستوى {level + 1}</span></div></td><td className="p-3 text-muted-foreground">{parent ? <span>{parent.nameAr} <span dir="ltr" className="text-xs">{parent.code}</span></span> : "—"}</td><td className="p-3 text-muted-foreground">{account.accountType}</td><td className="p-3">{account.isPosting ? <Badge className="bg-[#e8f5eb] text-[#1b6a40]">يسمح بالترحيل</Badge> : <Badge variant="outline">رئيسي</Badge>}</td></tr>; })}</tbody></table></div> : <Empty icon={BookOpenCheck} title="لم يُهيأ دليل الحسابات" description="أكمل إعداد الشركة لإنشاء الدليل الأساسي." />}</CardContent></Card>; }

function LedgerReport({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const ledger = trpc.operations.ledger.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled: Boolean(tenantId && companyId) }); if (!tenantId || !companyId) return null; return <Card className="mt-5 overflow-hidden border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">الأستاذ العام</CardTitle><p className="text-sm text-muted-foreground">حركة تفصيلية قابلة للتتبع من القيود المرحلة إلى الحسابات.</p></CardHeader><CardContent>{ledger.isLoading ? <Loader2 className="h-5 w-5 animate-spin text-[#0b3d3a]" /> : ledger.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-right text-sm"><thead className="border-b text-xs text-muted-foreground"><tr><th className="p-3">التاريخ</th><th className="p-3">القيد</th><th className="p-3">الحساب</th><th className="p-3">الوصف</th><th className="p-3">مدين</th><th className="p-3">دائن</th></tr></thead><tbody>{ledger.data.map((line, index) => <tr key={`${line.entryNumber}-${index}`} className="border-b last:border-0"><td className="p-3" dir="ltr">{new Date(line.entryDate).toLocaleDateString("en-CA")}</td><td className="p-3" dir="ltr">{line.entryNumber}</td><td className="p-3">{line.accountName} <span className="text-xs text-muted-foreground" dir="ltr">{line.accountCode}</span></td><td className="p-3 text-muted-foreground">{line.description}</td><td className="p-3" dir="ltr">{formatMoney(line.debit)}</td><td className="p-3" dir="ltr">{formatMoney(line.credit)}</td></tr>)}</tbody></table></div> : <Empty icon={BookOpenCheck} title="لا توجد حركة دفترية" description="ستظهر التفاصيل بعد ترحيل عمليات مالية." />}</CardContent></Card>; }

function OperationsConsole({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const enabled = Boolean(tenantId && companyId); const [supplierName, setSupplierName] = useState(""); const [bankName, setBankName] = useState(""); const [iban, setIban] = useState(""); const [expenseNumber, setExpenseNumber] = useState(""); const [expenseAmount, setExpenseAmount] = useState(""); const [expenseDescription, setExpenseDescription] = useState(""); const supplier = trpc.operations.createSupplier.useMutation({ onSuccess: () => { toast.success("تم إنشاء المورد."); setSupplierName(""); }, onError: (e) => toast.error(e.message) }); const bank = trpc.operations.createBankAccount.useMutation({ onSuccess: () => { toast.success("تمت إضافة الحساب البنكي."); setBankName(""); setIban(""); }, onError: (e) => toast.error(e.message) }); const expense = trpc.operations.recordExpense.useMutation({ onSuccess: (result) => { toast.success(`سُجل المصروف بالقيد ${result.journalEntryId}.`); setExpenseAmount(""); setExpenseDescription(""); }, onError: (e) => toast.error(e.message) }); if (!enabled) return <Card className="border-0 shadow-sm rounded-2xl"><CardContent className="p-8"><Empty icon={Building2} title="أكمل إعداد الشركة أولاً" description="يلزم إعداد الشركة ودليل الحسابات والفترة المالية قبل تسجيل المصروفات والحسابات البنكية." /></CardContent></Card>; return <section className="grid gap-5 xl:grid-cols-3"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">مورد جديد</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="اسم المورد" value={supplierName} onChange={setSupplierName} /><Button disabled={!supplierName || supplier.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => supplier.mutate({ tenantId: tenantId!, companyId: companyId!, name: supplierName })}>إضافة مورد</Button><p className="text-xs leading-5 text-muted-foreground">يمكن ربط المورد بسطر الدائن عند تسجيل مصروف أو فاتورة مورد لاحقاً.</p></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">حساب بنكي</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="اسم البنك" value={bankName} onChange={setBankName} /><Field label="IBAN" value={iban} onChange={setIban} dir="ltr" /><Button disabled={!bankName || bank.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => bank.mutate({ tenantId: tenantId!, companyId: companyId!, bankName, iban: iban || undefined })}>إضافة حساب بنكي</Button><p className="text-xs leading-5 text-muted-foreground">يربط الحساب تلقائياً بحساب النقد والبنوك في دليل الحسابات.</p></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">تسجيل مصروف مستحق</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="رقم القيد" value={expenseNumber} onChange={setExpenseNumber} placeholder="EXP-2026-000001" dir="ltr" /><Field label="قيمة المصروف" value={expenseAmount} onChange={setExpenseAmount} inputMode="decimal" dir="ltr" /><label className="text-sm font-medium text-[#44564d]">الوصف<Textarea className="mt-2" value={expenseDescription} onChange={(event) => setExpenseDescription(event.target.value)} /></label><Button disabled={!expenseNumber || !expenseAmount || !expenseDescription || expense.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => expense.mutate({ tenantId: tenantId!, companyId: companyId!, entryNumber: expenseNumber, entryDate: new Date().toISOString().slice(0, 10), amount: expenseAmount, description: expenseDescription })}>تسجيل وترحيل المصروف</Button></CardContent></Card></section>; }

function BankReconciliationPanel({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const enabled = Boolean(tenantId && companyId); const board = trpc.operations.reconciliationBoard.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const [bankId, setBankId] = useState(""); const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [reference, setReference] = useState(""); const [amount, setAmount] = useState(""); const [direction, setDirection] = useState<"inflow" | "outflow">("inflow"); const [paymentId, setPaymentId] = useState(""); const refresh = () => board.refetch(); const addLine = trpc.operations.addBankStatementLine.useMutation({ onSuccess: () => { toast.success("أُضيف سطر كشف الحساب."); setReference(""); setAmount(""); refresh(); }, onError: (e) => toast.error(e.message) }); const match = trpc.operations.matchBankStatementLine.useMutation({ onSuccess: () => { toast.success("تمت المطابقة البنكية."); refresh(); }, onError: (e) => toast.error(e.message) }); if (!enabled) return null; return <section className="mt-5 grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">إدخال سطر كشف حساب</CardTitle></CardHeader><CardContent className="space-y-3"><label className="text-sm font-medium text-[#44564d]">الحساب البنكي<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={bankId} onChange={(event) => setBankId(event.target.value)}><option value="">اختر حساباً</option>{board.data?.banks.map((bank) => <option key={bank.id} value={bank.id}>{bank.bankName} {bank.iban ? `— ${bank.iban}` : ""}</option>)}</select></label><Field label="تاريخ الحركة" value={date} onChange={setDate} dir="ltr" /><Field label="مرجع البنك" value={reference} onChange={setReference} dir="ltr" /><Field label="المبلغ" value={amount} onChange={setAmount} inputMode="decimal" dir="ltr" /><label className="text-sm font-medium text-[#44564d]">اتجاه الحركة<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={direction} onChange={(event) => setDirection(event.target.value as typeof direction)}><option value="inflow">داخل</option><option value="outflow">خارج</option></select></label><Button className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={!bankId || !amount || addLine.isPending} onClick={() => addLine.mutate({ tenantId: tenantId!, companyId: companyId!, bankAccountId: Number(bankId), transactionDate: date, reference: reference || undefined, amount, direction })}>إضافة سطر كشف</Button></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">مطابقة التحصيلات</CardTitle><p className="text-sm text-muted-foreground">لا تتم المطابقة إلا عندما يتطابق الحساب والاتجاه والمبلغ؛ وإلا تبقى للمراجعة البشرية.</p></CardHeader><CardContent className="space-y-4"><label className="text-sm font-medium text-[#44564d]">التحصيل المرشح<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={paymentId} onChange={(event) => setPaymentId(event.target.value)}><option value="">اختر تحصيلاً</option>{board.data?.receipts.map((receipt) => <option key={receipt.id} value={receipt.id}>{receipt.paymentNumber} — {receipt.amount}</option>)}</select></label>{board.data?.lines.length ? <div className="space-y-2">{board.data.lines.map((line) => <div key={line.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#e4e9e4] p-3 text-sm"><div><p className="font-medium" dir="ltr">{line.reference ?? `LINE-${line.id}`} · {line.amount}</p><p className="mt-1 text-xs text-muted-foreground">{line.direction} · {line.reconciliationStatus}</p></div>{line.reconciliationStatus === "unmatched" ? <Button size="sm" variant="outline" disabled={!paymentId || match.isPending} onClick={() => match.mutate({ tenantId: tenantId!, companyId: companyId!, statementLineId: line.id, paymentId: Number(paymentId) })}>مطابقة التحصيل</Button> : <Badge className="bg-[#e8f5eb] text-[#1b6a40]">مطابق</Badge>}</div>)}</div> : <Empty icon={Landmark} title="لا توجد سطور كشف" description="أدخل سطراً يدوياً أو اربط استيراد كشف الحساب ضمن دورة التكامل اللاحقة." />}</CardContent></Card></section>; }

function TaxCenter({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const enabled = Boolean(tenantId && companyId); const data = trpc.compliance.dashboard.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const vat = trpc.compliance.vatSummary.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const readiness = trpc.compliance.readiness.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); return <><Card className="border-0 shadow-sm rounded-2xl lg:col-span-3"><CardContent className="p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-bold text-[#1c3833]">فحص الجاهزية السعودية</p><p className="mt-1 text-sm text-muted-foreground">VAT، الفترة المفتوحة، هوية العملاء، وفحوصات الفواتير.</p></div><span className="text-2xl font-bold text-[#0b3d3a]" dir="ltr">{readiness.isLoading ? "…" : `${readiness.data?.score ?? 0}%`}</span></div><div className="mt-4 grid gap-2 sm:grid-cols-4">{readiness.data?.checks.map((check) => <div key={check.key} className={`rounded-xl p-3 text-sm ${check.passed ? "bg-[#eaf6ed] text-[#17633b]" : "bg-[#fff4e5] text-[#956018]"}`}>{check.passed ? "✓" : "!"} {check.label}</div>)}</div></CardContent></Card><section className="grid gap-5 lg:grid-cols-3"><Card className="border-0 shadow-sm rounded-2xl lg:col-span-2"><CardContent className="p-7"><div className="flex items-start gap-4"><div className="h-11 w-11 rounded-xl bg-[#fff2df] text-[#996313] flex items-center justify-center"><ShieldCheck className="h-5 w-5" /></div><div><p className="font-bold text-[#1c3833]">لوحة جاهزية الامتثال</p><p className="mt-2 max-w-xl text-sm leading-6 text-[#65726b]">تظهر نتائج الفحص البنيوي وحالات طابور الامتثال الناتجة عن الفواتير المصدرة. لا تعني حالة الطابور نجاح إرسال رسمي أو اعتماداً نظامياً.</p></div></div><div className="mt-6 grid gap-3 sm:grid-cols-3">{[["فواتير تتطلب مراجعة", data.data?.reviewCount], ["مهام امتثال معلقة", data.data?.queuedCount], ["مهام فاشلة", data.data?.failedCount]].map(([label, value]) => <div key={label as string} className="rounded-xl bg-[#f7f9f7] p-4"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-2 text-xl font-bold text-[#203b34]" dir="ltr">{data.isLoading ? "…" : value ?? "—"}</p></div>)}</div><div className="mt-6 space-y-3">{data.data?.submissions.length ? data.data.submissions.map((submission) => <div key={submission.id} className="flex items-center justify-between rounded-xl border border-[#e4e9e4] p-3 text-sm"><div><p className="font-medium text-[#31463d]" dir="ltr">{submission.invoiceNumber}</p><p className="mt-1 text-xs text-muted-foreground">{submission.operation}</p></div><Badge variant="outline">{submission.status}</Badge></div>) : <p className="rounded-xl border border-dashed border-[#dce4dd] p-5 text-center text-sm text-muted-foreground">لا توجد طلبات امتثال بعد. ستنشأ الطلبات عند إصدار فواتير مؤهلة.</p>}</div></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl bg-[#203f38] text-white"><CardContent className="p-6"><p className="font-bold">تحضير VAT</p><div className="mt-4 space-y-3 text-sm text-white/85"><div className="flex justify-between"><span>مبيعات خاضعة</span><span dir="ltr">{formatMoney(vat.data?.taxableSales)}</span></div><div className="flex justify-between"><span>ضريبة مخرجات</span><span dir="ltr">{formatMoney(vat.data?.outputVat)}</span></div><div className="flex justify-between font-bold text-white"><span>صافي الضريبة الظاهر</span><span dir="ltr">{formatMoney(vat.data?.netVatDue)}</span></div></div><p className="mt-5 text-xs leading-5 text-white/65">{vat.data?.notice ?? "سيظهر ملخص ضريبة المخرجات بعد إصدار فواتير معتمدة."}</p><Button variant="secondary" className="mt-5 bg-white text-[#16352e] hover:bg-[#edf4ef]" onClick={() => window.location.assign("/sales")}>فحص فاتورة <ArrowLeft className="mr-2 h-4 w-4" /></Button></CardContent></Card></section></>; }

function DocumentRoom({ tenantId, companyId }: { tenantId?: number; companyId?: number }) {
  const enabled = Boolean(tenantId && companyId); const [file, setFile] = useState<File | null>(null); const [classification, setClassification] = useState<"zatca" | "vat" | "zakat" | "bank" | "audit" | "supplier" | "customer" | "contract" | "financial_statement" | "miscellaneous">("vat");
  const list = trpc.documents.list.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  const upload = trpc.documents.upload.useMutation({ onSuccess: () => { toast.success("رُفع المستند وفُهرس بنجاح."); setFile(null); list.refetch(); }, onError: (error) => toast.error(error.message) });
  const onUpload = () => { if (!file || !tenantId || !companyId) return; const reader = new FileReader(); reader.onload = () => { const value = reader.result; if (typeof value === "string") upload.mutate({ tenantId, companyId, classification, filename: file.name, mimeType: file.type || "application/pdf", dataBase64: value.split(",")[1] ?? "" }); }; reader.readAsDataURL(file); };
  if (!enabled) return <Card className="w-full min-w-0 overflow-hidden border-0 shadow-sm rounded-2xl"><CardContent className="min-w-0 p-6 sm:p-10"><Empty icon={Building2} title="أنشئ مساحة عمل أولاً" description="بعد تهيئة الشركة، ستتمكن من حفظ فهرس المستندات وربطها بسجلاتها المالية." /></CardContent></Card>;
  return <section className="grid gap-5 xl:grid-cols-[0.9fr_1.1fr]"><Card className="w-full min-w-0 overflow-hidden border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">رفع مستند مالي</CardTitle></CardHeader><CardContent className="space-y-4"><label className="text-sm font-medium text-[#44564d]">التصنيف<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={classification} onChange={(event) => setClassification(event.target.value as typeof classification)}>{[["vat", "VAT"], ["zatca", "ZATCA"], ["zakat", "زكاة"], ["bank", "بنك"], ["audit", "مراجعة"], ["supplier", "مورد"], ["customer", "عميل"], ["contract", "عقد"], ["financial_statement", "قائمة مالية"], ["miscellaneous", "أخرى"]].map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><Input type="file" accept="application/pdf,image/jpeg,image/png,image/webp,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={(event) => setFile(event.target.files?.[0] ?? null)} /><p className="text-xs leading-5 text-muted-foreground">PDF أو صورة أو CSV أو XLSX، بحد أقصى 10 ميغابايت. تحفظ البايتات في التخزين الكائني ولا تحفظ في قاعدة البيانات.</p><Button disabled={!file || upload.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={onUpload}>{upload.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}رفع وفهرسة المستند</Button></CardContent></Card><Card className="w-full min-w-0 overflow-hidden border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">فهرس المستندات</CardTitle></CardHeader><CardContent>{list.isLoading ? <Loader2 className="h-5 w-5 animate-spin text-[#0b3d3a]" /> : list.data?.length ? <div className="space-y-3">{list.data.map((document) => <a className="flex min-w-0 items-center justify-between gap-3 rounded-xl border border-[#e4e9e4] p-3 transition-colors hover:bg-[#f7f9f7]" key={document.id} href={document.url} target="_blank" rel="noreferrer"><div className="min-w-0"><p className="truncate font-medium text-[#29443b]">{document.filename}</p><p className="mt-1 text-xs text-muted-foreground">{document.classification} · {(document.sizeBytes / 1024).toFixed(1)} KB</p></div><FileText className="h-5 w-5 shrink-0 text-[#668074]" /></a>)}</div> : <Empty icon={FileText} title="لا توجد مستندات مفهرسة" description="ارفـع أول مستند مالي للبدء في حفظ الأثر والوصول." />}</CardContent></Card></section>;
}

function DocumentExtraction({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const enabled = Boolean(tenantId && companyId); const documents = trpc.documents.list.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0, classification: "supplier" }, { enabled }); const [documentId, setDocumentId] = useState(""); const extract = trpc.documents.extractSupplierInvoice.useMutation({ onError: (error) => toast.error(error.message) }); if (!enabled) return null; const data = extract.data?.extraction as { supplierName?: string | null; invoiceNumber?: string | null; invoiceDate?: string | null; supplierVatNumber?: string | null; subtotal?: string | null; vatAmount?: string | null; grandTotal?: string | null; suggestedExpenseAccountCode?: string | null; suggestedCostCenterCode?: string | null; confidence?: number; items?: { description: string; total?: string | null }[] } | undefined; return <section className="mt-5 grid gap-5 xl:grid-cols-[0.85fr_1.15fr]"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">استخراج فاتورة مورد</CardTitle><p className="text-sm text-muted-foreground">اختر مستنداً مصنفاً «مورد». لا ينشئ التحليل قيداً أو مصروفاً تلقائياً.</p></CardHeader><CardContent className="space-y-3"><label className="text-sm font-medium text-[#44564d]">مستند المورد<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={documentId} onChange={(event) => setDocumentId(event.target.value)}><option value="">اختر مستنداً</option>{documents.data?.filter((item) => ["application/pdf", "image/jpeg", "image/png", "image/webp"].includes(item.mimeType)).map((item) => <option key={item.id} value={item.id}>{item.filename}</option>)}</select></label><Button disabled={!documentId || extract.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => extract.mutate({ tenantId: tenantId!, companyId: companyId!, documentId: Number(documentId) })}>{extract.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}استخراج مقترح</Button></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">نتيجة قابلة للمراجعة</CardTitle></CardHeader><CardContent>{!data ? <Empty icon={FileText} title="لا توجد نتيجة بعد" description="ستظهر الحقول والأصناف المقترحة هنا بعد التحليل، ثم يراجعها المستخدم قبل أي اعتماد." /> : <div className="space-y-4 text-sm"><div className="grid gap-3 sm:grid-cols-2">{[["المورد", data.supplierName], ["رقم الفاتورة", data.invoiceNumber], ["التاريخ", data.invoiceDate], ["رقم VAT", data.supplierVatNumber], ["الإجمالي", data.grandTotal], ["الثقة", data.confidence != null ? `${Math.round(data.confidence * 100)}%` : null]].map(([label, value]) => <div key={label as string} className="rounded-xl bg-[#f7f9f7] p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 font-medium" dir={label === "رقم الفاتورة" || label === "رقم VAT" || label === "الإجمالي" ? "ltr" : undefined}>{value || "غير مستخرج"}</p></div>)}</div><div><p className="mb-2 font-medium">الأصناف المقترحة</p>{data.items?.length ? <div className="space-y-2">{data.items.map((item, index) => <div className="flex justify-between rounded-lg border border-[#e4e9e4] p-2" key={`${item.description}-${index}`}><span>{item.description}</span><span dir="ltr">{item.total ?? "—"}</span></div>)}</div> : <p className="text-muted-foreground">لم تُستخرج أصناف واضحة.</p>}</div><p className="rounded-xl bg-[#fff4e3] p-3 text-xs leading-5 text-[#7a5419]">المستخدم مسؤول عن مراجعة المورد والمبالغ والحساب المقترح ومركز التكلفة قبل الحفظ أو الترحيل.</p></div>}</CardContent></Card></section>; }

function ScheduleSettings({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const enabled = Boolean(tenantId && companyId); const schedules = trpc.scheduling.list.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const [type, setType] = useState<"vat_due" | "financial_digest" | "approval_pending" | "customer_payment_due">("vat_due"); const [cron, setCron] = useState("0 0 7 * * *"); const [active, setActive] = useState(true); const cronIsValid = /^\d+\s+\d+\s+\d+\s+(\*|\d+)\s+(\*|\d+)\s+(\*|\d+)$/.test(cron.trim()); const configure = trpc.scheduling.configure.useMutation({ onSuccess: (data) => { toast.success(`تم حفظ المهمة. التنفيذ التالي: ${data.nextExecutionAt ?? "يظهر في لوحة المهام"}`); schedules.refetch(); }, onError: (error) => toast.error(error.message === "400" ? "صيغة Cron غير صحيحة. استخدم ستة حقول UTC مثل: 0 0 7 * * *" : error.message) }); if (!enabled) return <Card className="mt-5 border-0 shadow-sm rounded-2xl"><CardContent className="p-7"><Empty icon={BellRing} title="أكمل إعداد الشركة أولاً" description="بعد تهيئة الشركة، يمكنك ربط تذكيرات VAT والتقارير الدورية بمهمة Heartbeat آمنة." /></CardContent></Card>; return <Card className="mt-5 border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">التذكيرات والتقارير الدورية</CardTitle><p className="text-sm text-muted-foreground">تعمل المهام بتوقيت UTC وبحد أدنى دقيقة واحدة. لا يُنشأ أي اعتماد مالي تلقائي.</p></CardHeader><CardContent className="grid gap-4 lg:grid-cols-[1fr_1fr_1fr_auto]"><label className="text-sm font-medium text-[#44564d]">النوع<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={type} onChange={(event) => setType(event.target.value as typeof type)}><option value="vat_due">تذكير VAT</option><option value="financial_digest">ملخص مالي دوري</option><option value="approval_pending">اعتمادات معلقة</option><option value="customer_payment_due">مستحقات العملاء</option></select></label><div><Field label="Cron (UTC)" value={cron} onChange={setCron} dir="ltr" placeholder="0 0 7 * * *" /><p className={`mt-1 text-xs ${cronIsValid ? "text-muted-foreground" : "text-red-600"}`} dir="rtl">{cronIsValid ? "ستة حقول UTC: ثانية، دقيقة، ساعة، يوم، شهر، يوم أسبوع." : "أدخل ستة حقول مفصولة بمسافات، مثل: 0 0 7 * * *"}</p></div><label className="flex items-end gap-2 pb-3 text-sm font-medium text-[#44564d]"><input type="checkbox" checked={active} onChange={(event) => setActive(event.target.checked)} />مفعّل</label><Button className="self-end bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={configure.isPending || !cronIsValid} onClick={() => configure.mutate({ tenantId: tenantId!, companyId: companyId!, reminderType: type, cronExpression: cron.trim(), enabled: active })}>{configure.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}حفظ المهمة</Button><div className="lg:col-span-4">{schedules.data?.length ? <div className="mt-2 space-y-2">{schedules.data.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-[#f7f9f7] p-3 text-sm"><span>{item.reminderType}</span><span dir="ltr">{item.cronExpression}</span><Badge variant={item.isEnabled ? "default" : "outline"}>{item.isEnabled ? "مفعّل" : "متوقف"}</Badge></div>)}</div> : <p className="mt-2 text-sm text-muted-foreground">لا توجد مهام مهيأة لهذه الشركة.</p>}</div></CardContent></Card>; }

function TaxFirstWorkspaceSetup({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const [vatNumber, setVatNumber] = useState<string>(DEFAULT_WORKSPACE_SETUP.vatNumber); const [legalName, setLegalName] = useState<string>(DEFAULT_WORKSPACE_SETUP.legalName); const [legalNameAr, setLegalNameAr] = useState<string>(DEFAULT_WORKSPACE_SETUP.legalNameAr); const workspaces = trpc.finance.listMyWorkspaces.useQuery(); const bootstrap = trpc.finance.bootstrapWorkspace.useMutation({ onSuccess: () => { toast.success("تم إنشاء مساحة العمل بالرقم الضريبي. أكمل بيانات التشغيل أدناه."); workspaces.refetch(); }, onError: (error) => toast.error(error.message) }); if (tenantId && companyId) return <CompanySetup tenantId={tenantId} companyId={companyId} />; return <section className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><div className="flex items-center gap-3"><div className="h-10 w-10 rounded-xl bg-[#e6f0eb] text-[#0b3d3a] flex items-center justify-center"><Building2 className="h-5 w-5" /></div><div><CardTitle className="text-base">1. إنشاء الشركة</CardTitle><p className="mt-1 text-sm text-muted-foreground">يُستخدم الرقم الضريبي السعودي للتحقق، ويولّد النظام المعرّف الداخلي تلقائياً.</p></div></div></CardHeader><CardContent><form className="space-y-5" onSubmit={(event) => { event.preventDefault(); bootstrap.mutate(toWorkspaceBootstrapInput({ vatNumber, legalName, legalNameAr })); }}><Field label="الرقم الضريبي السعودي" value={vatNumber} onChange={setVatNumber} placeholder="310000000000003" inputMode="numeric" dir="ltr" help="15 رقماً؛ لا يظهر المعرّف الداخلي في هذه الخطوة." /><Field label="الاسم القانوني" value={legalName} onChange={setLegalName} dir="ltr" /><Field label="الاسم القانوني بالعربية" value={legalNameAr} onChange={setLegalNameAr} /><Button type="submit" disabled={bootstrap.isPending} className="bg-[#0b3d3a] hover:bg-[#082f2d]">{bootstrap.isPending ? <Loader2 className="ml-2 h-4 w-4 animate-spin" /> : <Plus className="ml-2 h-4 w-4" />}إنشاء مساحة العمل</Button></form></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardContent className="p-6"><p className="text-sm font-bold text-[#274239]">خريطة الإعداد المنضبط</p><div className="mt-5 space-y-4">{["الرقم الضريبي وبيانات الشركة", "الفروع ومراكز التكلفة والمشاريع", "السنة والفترات المحاسبية", "دليل الحسابات وسياسات الاعتماد", "قالب الفاتورة والتكاملات"].map((item, index) => <div className="flex gap-3" key={item}><div className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-[#eef3ef] text-xs font-bold text-[#527062]">{index + 1}</div><p className="text-sm text-[#64716a]">{item}</p></div>)}</div></CardContent></Card></section>; }

function CompanySetup({ tenantId, companyId }: { tenantId?: number; companyId?: number }) {
  const [vatNumber, setVatNumber] = useState(""); const [city, setCity] = useState("الرياض");
  const [periodStart, setPeriodStart] = useState("2026-01-01"); const [periodEnd, setPeriodEnd] = useState("2026-12-31"); const [fiscalYearStartMonth, setFiscalYearStartMonth] = useState("1");
  const status = trpc.finance.onboardingStatus.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled: Boolean(tenantId && companyId) });
  const seedRbac = trpc.rbac.seedDefaults.useMutation({ onError: (error) => toast.error(`تم إعداد الشركة، لكن تعذر تهيئة الصلاحيات: ${error.message}`) });
  const configure = trpc.finance.configureCompany.useMutation({ onSuccess: (result) => { toast.success(`اكتمل إعداد الشركة وإضافة ${result.createdAccounts} حسابات مبدئية.`); status.refetch(); if (tenantId && companyId) seedRbac.mutate({ tenantId, companyId }); }, onError: (error) => toast.error(error.message) });
  const configureWorkspace = (event: FormEvent) => { event.preventDefault(); if (tenantId && companyId) configure.mutate(toSingleCompanyConfigureInput({ tenantId, companyId, vatNumber, city, fiscalYearStartMonth, periodStart, periodEnd })); };
  return <section className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e6f0eb] text-[#0b3d3a]"><Building2 className="h-5 w-5" /></div><div><CardTitle className="text-base">إعداد التشغيل للشركة الموحدة</CardTitle><p className="mt-1 text-sm text-muted-foreground">تُستكمل بيانات الشركة والفترة ودليل الحسابات على مستوى شركة واحدة، دون إعداد فروع.</p></div></div></CardHeader><CardContent><form className="space-y-4" onSubmit={configureWorkspace}><div className="grid gap-4 sm:grid-cols-2"><Field label="الرقم الضريبي" value={vatNumber} onChange={setVatNumber} dir="ltr" placeholder="الرقم الضريبي للشركة" /><Field label="المدينة" value={city} onChange={setCity} /></div><div className="grid gap-4 sm:grid-cols-3"><Field label="بداية الفترة" value={periodStart} onChange={setPeriodStart} dir="ltr" /><Field label="نهاية الفترة" value={periodEnd} onChange={setPeriodEnd} dir="ltr" /><Field label="شهر بداية السنة" value={fiscalYearStartMonth} onChange={setFiscalYearStartMonth} inputMode="numeric" dir="ltr" /></div><Button type="submit" disabled={configure.isPending} className="bg-[#0b3d3a] hover:bg-[#082f2d]">{configure.isPending && <Loader2 className="ml-2 h-4 w-4 animate-spin" />}تهيئة الشركة ودليل الحسابات</Button>{status.data && <p className="text-xs text-[#5b7064]">الحالة: {status.data.accountCount} حسابات و{status.data.periodCount} فترات مالية.</p>}</form></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardContent className="p-6"><p className="text-sm font-bold text-[#274239]">خريطة الإعداد المنضبط</p><div className="mt-5 space-y-4">{["بيانات الشركة والرقم الضريبي", "مراكز التكلفة والمشاريع", "السنة والفترات المحاسبية", "دليل الحسابات وسياسات الاعتماد", "قالب الفاتورة والتكاملات"].map((item, index) => <div className="flex gap-3" key={item}><div className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-[#eef3ef] text-xs font-bold text-[#527062]">{index + 1}</div><p className="text-sm text-[#64716a]">{item}</p></div>)}</div></CardContent></Card></section>;
}

function SetupManagement({ tenantId, companyId }: { tenantId?: number; companyId?: number }) {
  const enabled = Boolean(tenantId && companyId); const data = trpc.finance.setupData.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled });
  const [branchCode, setBranchCode] = useState(""); const [branchName, setBranchName] = useState(""); const [centerCode, setCenterCode] = useState(""); const [centerName, setCenterName] = useState(""); const [projectCode, setProjectCode] = useState(""); const [projectName, setProjectName] = useState("");
  const [periodName, setPeriodName] = useState(""); const [periodStart, setPeriodStart] = useState("2026-01-01"); const [periodEnd, setPeriodEnd] = useState("2026-12-31"); const [documentType, setDocumentType] = useState<"invoice" | "quotation" | "credit_note" | "debit_note" | "journal" | "payment">("invoice"); const [prefix, setPrefix] = useState("INV-"); const [nextNumber, setNextNumber] = useState("1");
  const refreshed = () => data.refetch(); const branch = trpc.finance.addBranch.useMutation({ onSuccess: refreshed, onError: (e) => toast.error(e.message) }); const center = trpc.finance.addCostCenter.useMutation({ onSuccess: refreshed, onError: (e) => toast.error(e.message) }); const project = trpc.finance.addProject.useMutation({ onSuccess: refreshed, onError: (e) => toast.error(e.message) }); const period = trpc.finance.addFiscalPeriod.useMutation({ onSuccess: refreshed, onError: (e) => toast.error(e.message) }); const rule = trpc.finance.saveNumberingRule.useMutation({ onSuccess: () => { toast.success("حُفظت قاعدة الترقيم."); refreshed(); }, onError: (e) => toast.error(e.message) });
  if (!enabled) return null;
  return <section className="mt-5 grid gap-5 xl:grid-cols-3"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">الفروع والبعد التشغيلي</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="رمز فرع جديد" value={branchCode} onChange={setBranchCode} dir="ltr" /><Field label="اسم الفرع" value={branchName} onChange={setBranchName} /><Button disabled={!branchCode || !branchName || branch.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => branch.mutate({ tenantId: tenantId!, companyId: companyId!, code: branchCode, nameAr: branchName })}>إضافة فرع</Button><p className="text-xs text-muted-foreground">{data.data?.branches.length ?? 0} فروع مهيأة</p><Separator /><Field label="رمز مركز تكلفة" value={centerCode} onChange={setCenterCode} dir="ltr" /><Field label="اسم مركز التكلفة" value={centerName} onChange={setCenterName} /><Button disabled={!centerCode || !centerName || center.isPending} variant="outline" className="w-full" onClick={() => center.mutate({ tenantId: tenantId!, companyId: companyId!, code: centerCode, nameAr: centerName })}>إضافة مركز تكلفة</Button><p className="text-xs text-muted-foreground">{data.data?.costCenters.length ?? 0} مراكز تكلفة</p></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">المشاريع والفترات</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="رمز المشروع" value={projectCode} onChange={setProjectCode} dir="ltr" /><Field label="اسم المشروع" value={projectName} onChange={setProjectName} /><Button disabled={!projectCode || !projectName || project.isPending} variant="outline" className="w-full" onClick={() => project.mutate({ tenantId: tenantId!, companyId: companyId!, code: projectCode, nameAr: projectName })}>إضافة مشروع</Button><p className="text-xs text-muted-foreground">{data.data?.projects.length ?? 0} مشاريع</p><Separator /><Field label="اسم الفترة" value={periodName} onChange={setPeriodName} dir="ltr" /><div className="grid grid-cols-2 gap-2"><Field label="البداية" value={periodStart} onChange={setPeriodStart} dir="ltr" /><Field label="النهاية" value={periodEnd} onChange={setPeriodEnd} dir="ltr" /></div><Button disabled={!periodName || period.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => period.mutate({ tenantId: tenantId!, companyId: companyId!, name: periodName, startDate: periodStart, endDate: periodEnd })}>إضافة فترة</Button><p className="text-xs text-muted-foreground">{data.data?.periods.length ?? 0} فترات مالية</p></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">سياسة ترقيم المستندات</CardTitle></CardHeader><CardContent className="space-y-3"><label className="text-sm font-medium text-[#44564d]">نوع المستند<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={documentType} onChange={(event) => setDocumentType(event.target.value as typeof documentType)}>{[["invoice", "فاتورة"], ["quotation", "عرض سعر"], ["credit_note", "إشعار دائن"], ["debit_note", "إشعار مدين"], ["journal", "قيد يومية"], ["payment", "تحصيل أو دفع"]].map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><Field label="بادئة المستند" value={prefix} onChange={setPrefix} dir="ltr" /><Field label="رقم البداية التالي" value={nextNumber} onChange={setNextNumber} inputMode="numeric" dir="ltr" /><Button disabled={!prefix || !nextNumber || rule.isPending} className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" onClick={() => rule.mutate({ tenantId: tenantId!, companyId: companyId!, documentType, prefix, nextNumber: Number(nextNumber), padding: 6 })}>حفظ قاعدة الترقيم</Button><Separator /><p className="text-sm font-medium text-[#34473d]">القواعد النشطة</p><div className="space-y-2">{data.data?.numberingRules.map((item) => <div key={item.id} className="flex justify-between rounded-lg bg-[#f7f9f7] p-2 text-xs"><span>{item.documentType}</span><span dir="ltr">{item.prefix}{String(item.nextNumber).padStart(item.padding, "0")}</span></div>)}</div></CardContent></Card></section>;
}

function TaxAndInvoiceSettings({ tenantId, companyId }: { tenantId?: number; companyId?: number }) { const enabled = Boolean(tenantId && companyId); const data = trpc.finance.setupData.useQuery({ tenantId: tenantId ?? 0, companyId: companyId ?? 0 }, { enabled }); const vatExisting = data.data?.taxProfiles.find((item) => item.taxType === "vat"); const [registrationNumber, setRegistrationNumber] = useState(""); const [rate, setRate] = useState("1500"); const [frequency, setFrequency] = useState<"monthly" | "quarterly" | "annual">("quarterly"); const [taxPeriodName, setTaxPeriodName] = useState(""); const [taxPeriodStart, setTaxPeriodStart] = useState("2026-01-01"); const [taxPeriodEnd, setTaxPeriodEnd] = useState("2026-03-31"); const [terms, setTerms] = useState("30"); const [invoiceType, setInvoiceType] = useState<"standard" | "simplified">("standard"); const [footer, setFooter] = useState(""); const refreshed = () => data.refetch(); const saveProfile = trpc.finance.saveTaxProfile.useMutation({ onSuccess: () => { toast.success("حُفظ ملف VAT."); refreshed(); }, onError: (e) => toast.error(e.message) }); const addPeriod = trpc.finance.addTaxPeriod.useMutation({ onSuccess: refreshed, onError: (e) => toast.error(e.message) }); const savePreferences = trpc.finance.saveInvoicingPreferences.useMutation({ onSuccess: () => { toast.success("حُفظت تفضيلات الفوترة."); refreshed(); }, onError: (e) => toast.error(e.message) }); if (!enabled) return null; return <section className="mt-5 grid gap-5 xl:grid-cols-3"><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">ملف VAT</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="رقم التسجيل" value={registrationNumber || vatExisting?.registrationNumber || ""} onChange={setRegistrationNumber} dir="ltr" /><Field label="النسبة الافتراضية (نقاط أساس)" value={rate} onChange={setRate} inputMode="numeric" dir="ltr" /><label className="text-sm font-medium text-[#44564d]">دورية الإقرار<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={frequency} onChange={(event) => setFrequency(event.target.value as typeof frequency)}><option value="monthly">شهري</option><option value="quarterly">ربع سنوي</option><option value="annual">سنوي</option></select></label><Button className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={saveProfile.isPending} onClick={() => saveProfile.mutate({ tenantId: tenantId!, companyId: companyId!, taxType: "vat", registrationNumber: registrationNumber || vatExisting?.registrationNumber || undefined, defaultRateBps: Number(rate), filingFrequency: frequency })}>حفظ ملف VAT</Button></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">فترات VAT</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="اسم الفترة" value={taxPeriodName} onChange={setTaxPeriodName} dir="ltr" /><div className="grid grid-cols-2 gap-2"><Field label="البداية" value={taxPeriodStart} onChange={setTaxPeriodStart} dir="ltr" /><Field label="النهاية" value={taxPeriodEnd} onChange={setTaxPeriodEnd} dir="ltr" /></div><Button className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={!taxPeriodName || !vatExisting || addPeriod.isPending} onClick={() => addPeriod.mutate({ tenantId: tenantId!, companyId: companyId!, taxProfileId: vatExisting!.id, name: taxPeriodName, startDate: taxPeriodStart, endDate: taxPeriodEnd })}>إضافة فترة VAT</Button><div className="space-y-2">{data.data?.taxPeriods.map((item) => <div key={item.id} className="flex justify-between rounded-lg bg-[#f7f9f7] p-2 text-xs"><span>{item.name}</span><Badge variant="outline">{item.status}</Badge></div>)}</div></CardContent></Card><Card className="border-0 shadow-sm rounded-2xl"><CardHeader><CardTitle className="text-base">تفضيلات إصدار الفاتورة</CardTitle></CardHeader><CardContent className="space-y-3"><Field label="أيام السداد الافتراضية" value={terms} onChange={setTerms} inputMode="numeric" dir="ltr" /><label className="text-sm font-medium text-[#44564d]">نوع الفاتورة الافتراضي<select className="mt-2 h-11 w-full rounded-md border border-[#dce4dd] bg-white px-3 text-sm" value={invoiceType} onChange={(event) => setInvoiceType(event.target.value as typeof invoiceType)}><option value="standard">ضريبية</option><option value="simplified">مبسطة</option></select></label><label className="text-sm font-medium text-[#44564d]">ملاحظة تذييل الفاتورة<Textarea className="mt-2" value={footer} onChange={(event) => setFooter(event.target.value)} /></label><Button className="w-full bg-[#0b3d3a] hover:bg-[#082f2d]" disabled={savePreferences.isPending} onClick={() => savePreferences.mutate({ tenantId: tenantId!, companyId: companyId!, defaultPaymentTermsDays: Number(terms), defaultInvoiceType: invoiceType, footerNoteAr: footer || undefined })}>حفظ التفضيلات</Button></CardContent></Card></section>; }

function Field({ label, value, onChange, placeholder, inputMode, help, dir, disabled }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; inputMode?: "decimal" | "numeric"; help?: string; dir?: "rtl" | "ltr"; disabled?: boolean }) { return <div className="space-y-2"><Label className="text-[#44564d]">{label}</Label><Input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} inputMode={inputMode} dir={dir} disabled={disabled} className="h-11 border-[#dce4dd] bg-white focus-visible:ring-[#0b3d3a] disabled:cursor-not-allowed disabled:bg-[#edf1ee] disabled:text-muted-foreground" />{help && <p className="text-xs text-muted-foreground">{help}</p>}</div>; }
function Empty({ icon: Icon, title, description }: { icon: typeof FileText; title: string; description: string }) { return <div className="text-center"><div className="mx-auto h-12 w-12 rounded-2xl bg-[#eef4ef] text-[#6c917d] flex items-center justify-center"><Icon className="h-6 w-6" /></div><p className="mt-4 font-semibold text-[#3a4f45]">{title}</p><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted-foreground">{description}</p></div>; }
